import {mountChallenges} from './workshop-challenges.mjs';
import {copy,caseInfo} from './workshop-content.mjs';
import {createWorkshop,snapshot,required,measureWorkshop,diagnoseWorkshop,repairWorkshop,verifyWorkshop,hasEvidence} from './workshop-model.mjs';
import {initialLanguage} from './i18n.mjs';
import {mountWorkshopBench} from './workshop-bench.mjs';
import {mountBench} from '../autos/bench.mjs';
const $=s=>document.querySelector(s),add=(tag,text,host)=>{const e=document.createElement(tag);e.textContent=text;host.append(e);return e;};
let lang=initialLanguage(),kind=new URLSearchParams(location.search).get('case');if(!caseInfo[kind])kind='mechanics';let s=createWorkshop(kind),playing=false,cut=true,last=0,raf=0,visible=true,message='',diagnosis='';let info=caseInfo[kind];const t=x=>x[lang],w=k=>t(copy[k]),fmt=n=>new Intl.NumberFormat(lang==='es'?'es-CO':'en-US',{maximumFractionDigits:2}).format(n);
const a=mountWorkshopBench($('#normalView'),kind,'A'),b=mountWorkshopBench($('#actualView'),kind,'B');if(a&&b){a.onView(v=>b.setView(v));b.onView(v=>a.setView(v));}const electric=kind==='mechanics'?mountBench($('#electricView'),'electric'):null;
function persistLocale(){try{localStorage.setItem('mecanica.locale.v1',lang);}catch{}const u=new URL(location.href);u.searchParams.set('lang',lang);u.searchParams.set('case',kind);history.replaceState(null,'',u);}
function readings(m,id){switch(id){case 'battery':return 'V = '+fmt(m.rest)+' V → '+fmt(m.loaded)+' V';case 'ground':return 'ΔV = '+fmt(m.drop)+' V · '+fmt(m.rpm)+' rpm';case 'input':return 'Vin '+(lang==='es'?'pico':'peak')+' = '+fmt(m.inputPeak)+' V · G = '+m.gain;case 'output':return 'Vout '+(lang==='es'?'pico':'peak')+' = '+fmt(m.outputPeak)+' V · ±'+m.rail+' V · '+(m.clipped?(lang==='es'?'recorte':'clipped'):(lang==='es'?'lineal':'linear'));case 'speed':return 'v = '+fmt(m.speed)+' mm/s · p = '+m.pressure+' bar';case 'flow':return 'Q '+(lang==='es'?'entrada':'in')+' = '+fmt(m.inlet)+' L/min';case 'leak':return 'Q '+(lang==='es'?'fuga':'leak')+' = '+fmt(m.leak)+' L/min · Q '+(lang==='es'?'útil':'useful')+' = '+fmt(m.useful)+' L/min';case 'supply':return 'p = '+fmt(m.supply)+' bar · 1→2, 4→5';case 'exhaust':return 'pB = '+fmt(m.back)+' bar · F = '+fmt(m.force)+' N · v = '+m.speed+' mm/s';}}
function render(){document.documentElement.lang=lang;document.title=t(info.title)+' · EN/ES';$('#language').value=lang;persistLocale();const mapping={back:'back',languageLabel:'language',title:'title',normalTitle:'healthy',actualTitle:'actual',timeLabel:'time',motionNote:'motion',measureTitle:'measure',measureNote:'measureNote',diagnoseTitle:'diagnose',diagnosisLabel:'choose',confirm:'submit',repairTitle:'repair',verifyTitle:'verify',verify:'verify',restart:'reset',cut:'cut',logTitle:'log',limitsTitle:'limits',scope:'scope',guideTitle:'step'};for(const [id,key]of Object.entries(mapping))$('#'+id).textContent=w(key);
 $('#back').href='index.html?lang='+lang+'&track='+kind+'&lesson='+({mechanics:'nostart',electronics:'opamp',hydraulics:'hydrodiagnosis',pneumatics:'pneudiagnosis'})[kind];$('#caseTitle').textContent=t(info.title);$('#symptom').textContent=t(info.symptom);$('#limits').textContent=t(info.limit);$('#caseNav').replaceChildren();for(const [id,data]of Object.entries(caseInfo)){const link=add('a',t(data.title),$('#caseNav'));link.href='workshop.html?lang='+lang+'&case='+id;if(id===kind)link.setAttribute('aria-current','page');}
 $('#guide').replaceChildren();for(const text of info.guide)add('li',t(text),$('#guide'));$('#stage').textContent=s.verified?w('verified'):s.repaired?w('repaired'):s.diagnosed?w('diagnosed'):w('empty');$('#tests').replaceChildren();for(const id of required[kind]){const button=add('button',t(info.tests[id]),$('#tests'));button.dataset.test=id;button.onclick=()=>{playing=false;measureWorkshop(s,id);challenges?.measured(id);message='';const part=({battery:'battery',ground:'ground',input:'signals',output:'signals',speed:'piston',flow:'flow',leak:'leak',supply:'regulator',exhaust:'silencer'})[id];a?.select(part);b?.select(part);electric?.select(part);render();};}
 $('#diagnosis').replaceChildren();const placeholder=add('option',w('choose'),$('#diagnosis'));placeholder.value='';for(const [id,label]of Object.entries(info.options)){const option=add('option',t(label),$('#diagnosis'));option.value=id;}$('#diagnosis').value=diagnosis;$('#diagnosis').disabled=s.diagnosed;$('#confirm').disabled=s.diagnosed||!diagnosis;$('#repair').textContent=t(info.fix);$('#repair').disabled=!s.diagnosed||s.repaired;$('#verify').disabled=!s.repaired||s.verified;$('#feedback').textContent=message?copy[message]?w(message):'':'';$('#explanation').textContent=s.diagnosed?t(info.explain)+(s.verified?' '+w('success'):''):'';
 $('#empty').textContent=s.measurements.length?'':w('empty');$('#readings').replaceChildren();for(const m of s.measurements.slice().reverse()){const card=add('article','',$('#readings'));card.className='workshop-reading';add('h4',(m.repaired?w('after'):w('before'))+' · '+t(info.tests[m.id]),card);const pair=add('div','',card);pair.className='reading-pair';for(const [name,model]of [['healthy',m.normal],['actual',m.actual]]){const col=add('div','',pair);add('strong',w(name),col);add('p',readings(model,m.id),col);}}
 $('#signalArea').hidden=kind!=='electronics';$('#electricArea').hidden=kind!=='mechanics';$('#electricTitle').textContent=lang==='es'?'B · Batería, arranque y retorno de masa':'B · Battery, starter and ground return';if(!a)$('#normalView').textContent=w('no3d');if(!b)$('#actualView').textContent=w('no3d');if(electric&&!electric.debug)$('#electricView').textContent=w('no3d');challenges?.render();draw();}
function graph(){const root=$('#signal');root.replaceChildren();root.setAttribute('aria-label',lang==='es'?'Salida sana y salida del caso, voltios y milisegundos':'Healthy and case outputs, volts and milliseconds');const svg=(tag,attrs,text)=>{const e=document.createElementNS('http://www.w3.org/2000/svg',tag);for(const [k,v]of Object.entries(attrs))e.setAttribute(k,v);if(text)e.textContent=text;root.append(e);};for(const v of [-12,0,12]){const y=130-v*7;svg('line',{x1:50,x2:750,y1:y,y2:y,stroke:'#b3bda9'});svg('text',{x:0,y:y+5,fill:'#21392f','font-size':15},v+' V');}for(let j=0;j<5;j++)svg('text',{x:50+j*170,y:250,fill:'#21392f','font-size':15},j*10+' ms');for(const [healthy,color,label]of [[true,'#37786e','A'],[false,'#a25b2b','B']]){let path='';for(let i=0;i<=240;i++){const m=snapshot(s,healthy,s.time+i/240*4);path+=(i?'L':'M')+(50+i/240*680)+','+(130-m.output*7);}svg('path',{d:path,fill:'none',stroke:color,'stroke-width':3});svg('text',{x:healthy?150:450,y:20,fill:color,'font-size':16},label+' · Vout');}}
function draw(){const normal=snapshot(s,true),actual=snapshot(s);a?.draw(normal,s.time);b?.draw(actual,s.time);electric?.draw(actual,(s.time*actual.rpm/120*.15)%1);$('#time').value=Math.round(s.time*100);$('#play').textContent=w(playing?'pause':'play');$('#cut').setAttribute('aria-pressed',String(cut));$('#motionReadout').textContent=kind==='mechanics'?'A: '+normal.rpm+' rpm · B: '+actual.rpm+' rpm':kind==='electronics'?'A: '+fmt(normal.output)+' V · B: '+fmt(actual.output)+' V':'A: '+fmt(normal.position)+' mm · B: '+fmt(actual.position)+' mm · '+(actual.advance?(lang==='es'?'Avance':'Extension'):(lang==='es'?'Retorno':'Retraction'));if(kind==='electronics')graph();}
function animate(now){raf=0;if(!playing||!visible||document.hidden)return;const dt=last?Math.min(.05,(now-last)/1000):0;last=now;s.time+=dt*.5;if(s.time>=7.99){s.time=7.99;playing=false;}draw();if(playing)raf=requestAnimationFrame(animate);}
function schedule(){if(playing&&visible&&!document.hidden&&!raf){last=0;raf=requestAnimationFrame(animate);}}
new IntersectionObserver(([e])=>{visible=e.isIntersecting;schedule();}).observe($('#benches'));document.addEventListener('visibilitychange',schedule);matchMedia('(prefers-reduced-motion:reduce)').addEventListener('change',()=>{playing=false;draw();});
$('#language').onchange=e=>{lang=e.target.value;render();};$('#play').onclick=()=>{if(s.time>=7.99)s.time=0;playing=!playing;draw();schedule();};$('#time').oninput=e=>{playing=false;s.time=+e.target.value/100;draw();};$('#cut').onclick=()=>{cut=!cut;a?.setCut(cut);b?.setCut(cut);electric?.cut(cut);draw();};$('#diagnosis').onchange=e=>{diagnosis=e.target.value;$('#confirm').disabled=!diagnosis||s.diagnosed||!challenges.ready();};$('#confirm').onclick=()=>{if(!challenges.ready())return;message=diagnoseWorkshop(s,diagnosis);challenges?.diagnosed(message,diagnosis);render();};$('#repair').onclick=()=>{playing=false;if(repairWorkshop(s))message='repaired';render();};$('#verify').onclick=()=>{playing=false;message=verifyWorkshop(s)?'verified':'pending';if(s.verified){s.time=7.99;challenges?.completed();}render();};$('#restart').onclick=()=>{challenges?.reset();info=caseInfo[kind];s=createWorkshop(kind);diagnosis='';message='';playing=false;a?.select('');b?.select('');electric?.select('');render();};
const challenges=mountChallenges({get:()=>s,lang:()=>lang,kind,base:caseInfo[kind],start:(fault,data)=>{s=createWorkshop(kind);s.fault=fault;info=data;diagnosis='';message='';playing=false;render();},refresh:render});
render();window.workshopDebug=()=>({s,lang,normal:snapshot(s,true),actual:snapshot(s),a:a?.parts(),b:b?.parts(),playing});
